                  "terminal_send",
                  "terminal_signal",
                  "terminal_close",
                  "web_fetch",
                  "web_search",
                  "todo_write",
                  "skill",
                  "present"
                ],
                "modelPolicy": {
                  "mode": "inherit",
                  "routes": []
                },
                "memory": {
                  "read": [],
                  "write": []
                },
                "context": {
                  "handoff": true,
                  "memory": false
                }
              },
              {
                "id": "reviewer",
                "name": "Reviewer",
                "description": "Reviewer initial template",
                "prompt": "Use only the selected handoff; preserve its hard invariants and decided boundaries. Return a decision-changing unknown to Controller in FINAL if evidence changes direction, architecture, contract, scope or acceptance. Keep raw working context private; return distilled conclusion, findings, unknowns, contradictions, verification and optional Artifact refs. When an already discovered local fact changes your conclusion, local acceptance or a critical UNKNOWN and thaliris_observe is available, record it with source refs; the adapter binds task, handoff, candidate and requirement refs, so do not supply or reconstruct them. Without that tool, return the observation and its sources in FINAL. This adds no search obligation; do not reconstruct global requirements or judge their satisfaction, and treat historical observations as history, not current truth. When selected, independently challenge a converged candidate against original acceptance, hard invariants and cross-boundary behavior. Remain non-writing. Counterevidence is a finding; inadequate evidence stays unverified/insufficient; READY requires supported evidence for the selected review scope, not absence of blockers, and reports review findings rather than product completion. Bounded design-preserving defects support fresh ordinary correction; architecture/contract/invariant/scope/acceptance or decision-basis changes return to Controller.",
                "enabled": true,
                "tools": [
                  "read",
